    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            xx,yy=x+dx,y+dy
                            if 0<=xx<H and 0<=yy<W and not seen[xx][yy] and g[xx][yy]==col:
                                seen[xx][yy]=True; q.append((xx,yy))
                out.append((col,cells))
    return out
