from collections import deque as DQ
def solve(name):
    gi=G[name+' input']; H=len(gi); Wd=len(gi[0])
    bg=Counter(v for r in gi for v in r).most_common(1)[0][0]
    out=[r[:] for r in gi]
    dist={}
    dq=DQ()
    for i in range(H):
        for j in range(Wd):
            if gi[i][j]==bg and (i==0 or i==H-1 or j==0 or j==Wd-1):
                dist[(i,j)]=0; dq.append((i,j))
    while dq:
        x,y=dq.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            xx,yy=x+dx,y+dy
            if 0<=xx<H and 0<=yy<Wd and gi[xx][yy]==bg and (xx,yy) not in dist:
                dist[(xx,yy)]=dist[(x,y)]+1; dq.append((xx,yy))
    for i in range(H):
        for j in range(Wd):
            if gi[i][j]==bg and (i,j) not in dist:
                out[i][j]=2
            elif gi[i][j]==bg:
                out[i][j]=2
    return out,None

