from collections import Counter,deque as DQ
def ray(g,i,j,dx,dy,bgval):
    H,Wd=len(g),len(g[0])
    x,y=i+dx,j+dy;d=1
    while 0<=x<H and 0<=y<Wd:
        if g[x][y]!=bgval: return d,g[x][y]
