    H=len(gi);Wd=len(gi[0]); bg=Counter(v for r in gi for v in r).most_common(1)[0][0]
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    seen=[[False]*Wd for _ in range(H)]
    fills=[]
    for i in range(H):
        for j in range(Wd):
            if g_:=gi[i][j]; g_!=bg or seen[i][j]: continue
            q=DQ([(i,j)]);seen[i][j]=True;comp=[]
            while q:
                x,y=q.popleft();comp.append((x,y))
                for dx,dy in dirs:
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<Wd and gi[xx][yy]==bg and not seen[xx][yy]:
                        seen[xx][yy]=True;q.append((xx,yy))
            touch=any(x==0 or x==H-1 or y==0 or y==Wd-1 for x,y in comp)
            if not touch:
                cnt=Counter(); 
                for x,y in comp:
