import os,re
from collections import Counter,deque as DQ
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(g):
    H=len(g);Wd=len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    for i in range(H):
        for j in range(Wd):
            if g[i][j]!=bg: continue
            q=DQ([(i,j)]);seen=False;comp=[]
            # BFS from this cell only among bg
            st=[(i,j)];seen_cell={(i,j)};comp=[(i,j)]
            while st:
                x,y=st.pop()
                for dx,dy in dirs:
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<Wd and gi:=g[xx][yy]==bg and (xx,yy) not in seen_cell:
                        seen_cell.add((xx,yy)); comp.append((xx,yy)); st.append((xx,yy))
            touch=any(x==0 or x==H-1 or y==0 or y==Wd-1 for x,y in comp)
            if touch: continue
            cnt=Counter()
            for x,y in comp:
                for dx,dy in dirs:
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<Wd and g[xx][yy]!=bg: cnt[g[xx][yy]]+=1
            fill=cnt.most_common(1)[0][0] if cnt else 2
            for x,y in comp: out[x][y]=fill
    return out
for k in [1,2,3,5,6]:
    gi=G['Demo pair %d input'%k]; eo=G['Demo pair %d output'%k]; r=solve(gi)
    mis=[(i,j,gi[i][j],eo[i][j],r[i][j]) for i in range(len(eo)) for j in range(len(eo[0])) if r[i][j]!=eo[i][j]]
    print(k,'nmis',len(mis),mis[:8])

